{
  "policy_type": "rules",
  "name": "policy_ep_40",
  "rules": [
    {
      "if": [
        {"feature": "y", "op": "<", "value": 0.3},
        {"feature": "vy", "op": "<", "value": -0.5}
      ],
      "then": 2
    },
    {
      "if": [
        {"feature": "theta", "op": ">", "value": 0.1}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "theta", "op": "<", "value": -0.1}
      ],
      "then": 1
    },
    {
      "if": [
        {"feature": "vx", "op": ">", "value": 0.5}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "vx", "op": "<", "value": -0.5}
      ],
      "then": 1
    }
  ],
  "default_action": 0,
  "notes": "This initial policy aims to stabilize the lander by using the main engine to slow descent when close to the ground and using orientation engines to correct angular deviations and horizontal velocity. As there are no previous policies, this is a baseline to encourage safe landings and reduce crashes."
}

